mapper.sql:
p.`del_flag` = 0

    AND p.`project_no` LIKE CONCAT('%', #{q.projectNo}, '%')


    AND p.`project_name` LIKE CONCAT('%', #{q.projectName}, '%')


    AND p.`declare_dept` LIKE CONCAT('%', #{q.declareDept}, '%')


    AND p.`project_type` = #{q.projectType}


    AND p.`xzqh` = #{q.xzqh}


    AND p.`gnq` = #{q.gnq}


    AND p.`arg_result` = #{q.argResult}


    AND p.`status` = #{q.status}


    AND p.`tdzl_project` = #{q.tdzlProject}


    AND p.`declare_date` >= #{q.beginDeclareDate}


    AND p.`declare_date` <= #{q.endDeclareDate}


    AND p.`total_investment` >= #{q.beginInvestment}


    AND p.`total_investment` <= #{q.endInvestment}


    AND p.`facility_id` = #{q.facilityId}


    AND p.`crzdbh` LIKE CONCAT('%', #{q.crzdbh}, '%')


    AND p.`dkmc` LIKE CONCAT('%', #{q.dkmc}, '%')


    AND p.`create_time` >= CONCAT(#{q.beginCreateTime}, ' 00:00:00')


    AND p.`create_time` <= CONCAT(#{q.endCreateTime}, ' 23:59:59')



    AND (
        p.`project_name` LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.`project_summary` LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.`arg_reason` LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.`arg_content` LIKE CONCAT('%', #{q.keyword}, '%')
    )

mapper.select:
SELECT COUNT(1)
FROM `t_escalation_project` p
WHERE p.`del_flag` = 0
  AND p.`project_no` = #{projectNo}

    AND p.`id` <> #{excludeId}
